let S=null;
const LOCK="data:image/png;base64,",HERO="data:image/jpeg;base64,";
const c01=x=>Math.max(0,Math.min(1,x)),pr=(t,a,d)=>c01((t-a)/d);
const oB=(x,s=1.7)=>{x=c01(x)-1;return 1+(s+1)*x*x*x+s*x*x},oC=x=>1-Math.pow(1-c01(x),3),oQ=x=>{x=c01(x);return x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2};
const fmt=n=>Math.round(n).toLocaleString('en-US');
const INK='#0D0D0D',LIME='#B9FF66',PINK='#FF005A',WHITE='#F9FAFB',MUTED='#A1A1AA';
function mk(cls,css,html,tx=true){const d=document.createElement('div');d.className=cls+(tx?' tx line':'');Object.assign(d.style,css);d.innerHTML=html||'';S.appendChild(d);return d}
function lines(top,arr,t0,stg,fs,color){
 const b=mk('big blk',{left:'100px',top:top+'px',fontSize:fs+'px',color:color||WHITE},'');const ws=[];
 arr.forEach(l=>{const ld=document.createElement('div');ld.style.cssText='overflow:hidden;padding:0 0 .16em;margin-bottom:-.16em';(Array.isArray(l)?l:[l]).forEach(w=>{const[tx,c]=Array.isArray(w)?w:[w,''];const s=document.createElement('span');s.className='w '+c;s.textContent=tx;ld.appendChild(s);ws.push(s)});b.appendChild(ld)});
 return{el:b,draw(t,ex){ws.forEach((s,i)=>{const p=pr(t,t0+i*stg,.55),e=ex?pr(t,ex+i*.04,.3):0;s.style.transform=`translateY(${(1-oB(p,1.5))*118-e*118}%)`;s.style.opacity=(p>0&&e<1)?1:0})}}}
function glass(l,t,w,h,r=32){return mk('',{left:l+'px',top:t+'px',width:w+'px',height:h+'px',borderRadius:r+'px',background:'rgba(255,255,255,.05)',border:'2px solid rgba(255,255,255,.11)',boxSizing:'border-box'},'',false)}
function burst(cx,cy,t0,col,n=16){const P=[];for(let i=0;i<n;i++)P.push(mk('',{width:'14px',height:'14px',left:'0',top:'0',background:col,borderRadius:i%3?'3px':'50%',opacity:0},'',false));
 return t=>{const p=pr(t,t0,.7);P.forEach((d,i)=>{const a=i/n*6.283+.4,r=50+250*oC(p)*(.6+.4*((i*37)%10)/10);d.style.transform=`translate(${cx+Math.cos(a)*r}px,${cy+Math.sin(a)*r}px) rotate(${i*40+p*220}deg) scale(${1-p*.6})`;d.style.opacity=(p>0&&p<1)?1-p*p:0})}}
const END=3.4;
