 const dots=mk('',{left:'-60px',top:'-60px',width:'1200px',height:'2040px',backgroundImage:'radial-gradient(rgba(255,255,255,.08) 2.2px,transparent 2.8px)',backgroundSize:'54px 54px'},'',false);
 const vig=mk('',{left:'0',top:'0',width:'1080px',height:'1920px',background:'radial-gradient(ellipse at 50% 45%,rgba(13,13,13,0) 45%,rgba(13,13,13,.75) 100%)'},'',false);
 const cam=document.createElement('div');cam.className='cam';cam.style.cssText='position:absolute;left:0;top:0;width:1080px;height:1920px;transform-origin:50% 50%';st.appendChild(cam);S=cam;
 const logo=mk('',{left:'100px',top:'262px',width:'132px',height:'101px',background:WHITE,zIndex:'7',WebkitMask:`url(${LOCK}) left center/contain no-repeat`,mask:`url(${LOCK}) left center/contain no-repeat`},'',false);
 const tag=mk('mono blk',{left:'700px',top:'296px',width:'260px',textAlign:'right',color:cat==='hiring'?LIME:WHITE,letterSpacing:'2px'},cat==='hiring'?'● HIRING NOW':'● FOR STUDENTS');
 const draw=build();const orig=[...cam.children].filter(e=>e!==logo);
 const card=mk('',{left:'0',top:'0',width:'1080px',height:'1920px',background:LIME,backgroundImage:'radial-gradient(rgba(13,13,13,.10) 2.2px,transparent 2.8px)',backgroundSize:'54px 54px',zIndex:'5'},'',false);
 const lock=mk('',{left:'100px',top:'420px',width:'330px',height:'252px',background:INK,zIndex:'6',transformOrigin:'left center',WebkitMask:`url(${LOCK}) left center/contain no-repeat`,mask:`url(${LOCK}) left center/contain no-repeat`},'',false);
