 const st=mk('blk',{left:'130px',top:'1010px',border:'8px solid '+LIME,borderRadius:'20px',padding:'14px 36px',color:LIME,fontWeight:800,fontSize:'92px',letterSpacing:'-2px',background:'rgba(185,255,102,.08)'},'2026 LOW');
